<script setup lang="ts">
import { ArrowLeft, Box, Check, Image, MapPin, Pencil, RefreshCw, Sparkles, Trash2, Upload, User, Workflow, X } from 'lucide-vue-next'
import { computed, onMounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { api, mediaUrl, sleep } from '@/api'
import { appConfirm } from '@/shared/confirmDialog'
import { notice } from '@/shared/notice'
import type { Asset, Chapter } from '@/types'
import { AssetTypeEnum, TaskStatusEnum } from '@/types'
import CreativeCanvas from '@/features/workbench/pages/CreativeCanvas.vue'
const route = useRoute(); const router = useRouter()
const novelId = computed(() => Number(route.params.novelId)); const chapterId = computed(() => Number(route.params.chapterId)); const step = computed(() => Math.min(3, Number(route.params.stepId) || 1))
const chapter = ref<Chapter | null>(null); const assets = ref<Asset[]>([]); const extracting = ref(false); const processing = ref<number[]>([]); const editing = ref<Asset | null>(null); const editForm = ref({ canonical_name: '', aliases: '', description: '', base_traits: '' })
const batchGenerating = ref(false)
const steps = [{ id: 1, label: '内容理解', sub: '提取角色与场景', icon: User }, { id: 2, label: '视觉资产', sub: '统一人物与世界观', icon: Image }, { id: 3, label: '创作画布', sub: '分镜与视频生成', icon: Workflow }]
const groups = computed(() => [{ type: AssetTypeEnum.PERSON, label: '角色', icon: User }, { type: AssetTypeEnum.SCENE, label: '场景', icon: MapPin }, { type: AssetTypeEnum.ITEM, label: '道具', icon: Box }].map(group => ({ ...group, items: assets.value.filter(item => item.asset_type === group.type) })))
async function load() { try { const response = await api.workbenchBootstrap(novelId.value, chapterId.value); chapter.value = response.data.chapter; assets.value = response.data.assets } catch (error) { notice.error((error as Error).message) } }
async function poll(id: string) { let task = (await api.task(id)).data; while (![TaskStatusEnum.COMPLETED, TaskStatusEnum.FAILED, TaskStatusEnum.CANCELLED].includes(task.status)) { await sleep(2500); task = (await api.task(id)).data } return task }
async function extract() { extracting.value = true; try { const task = await poll((await api.extract(chapterId.value)).data.id); if (task.status !== TaskStatusEnum.COMPLETED) throw new Error(task.error_message || '提取失败'); await load(); notice.success('内容理解完成') } catch (error) { notice.error((error as Error).message) } finally { extracting.value = false } }
async function generate(asset: Asset) { processing.value.push(asset.id); try { const task = await poll((await api.generateAsset(asset.id)).data.id); if (task.status !== TaskStatusEnum.COMPLETED) throw new Error(task.error_message || '生成失败'); await load(); notice.success(`${asset.canonical_name} 主图已生成`) } catch (error) { notice.error((error as Error).message) } finally { processing.value = processing.value.filter(id => id !== asset.id) } }
async function batchGenerate() { const pending = assets.value.filter(item => !item.main_image); if (!pending.length) return notice.info('所有资产都已有主图'); batchGenerating.value = true; try { for (const asset of pending) await generate(asset); notice.success('批量生成完成') } finally { batchGenerating.value = false } }
async function upload(asset: Asset, event: Event) { const file = (event.target as HTMLInputElement).files?.[0]; if (!file) return; try { const result = await api.upload(file); await api.updateAsset(asset.id, { main_image: result.url || mediaUrl(`/media/${result.filename}`) }); await load(); notice.success('主图已更新') } catch (error) { notice.error((error as Error).message) } }
async function uploadAngle(asset: Asset, field: 'angle_image_1' | 'angle_image_2', event: Event) { const file = (event.target as HTMLInputElement).files?.[0]; if (!file) return; try { const result = await api.upload(file); await api.updateAsset(asset.id, { [field]: result.url || mediaUrl(`/media/${result.filename}`) }); await load(); notice.success('参考图已更新') } catch (error) { notice.error((error as Error).message) } }
async function removeAsset(asset: Asset) {
  if (!await appConfirm({
    title: `删除资产「${asset.canonical_name}」？`,
    message: '资产及其参考图片将被删除，且无法恢复。',
    confirmLabel: '删除资产',
    tone: 'danger',
  })) return
  await api.deleteAsset(asset.id)
  await load()
  notice.success('资产已删除')
}
function openEdit(asset: Asset) { editing.value = asset; editForm.value = { canonical_name: asset.canonical_name, aliases: asset.aliases?.join(', ') || '', description: asset.description || '', base_traits: asset.base_traits || '' } }
async function saveAsset() { if (!editing.value) return; await api.updateAsset(editing.value.id, { ...editForm.value, aliases: editForm.value.aliases.split(/[,，]/).map(value => value.trim()).filter(Boolean) }); editing.value = null; await load(); notice.success('资产已保存') }
function go(value: number) { router.push(`/novel/${novelId.value}/chapter/${chapterId.value}/step/${value}`) }
onMounted(load); watch(chapterId, load)
</script>
<template><div class="workflow-page"><header class="workflow-header"><div class="workflow-back"><RouterLink :to="`/novel/${novelId}`" class="icon-button"><ArrowLeft :size="17" /></RouterLink><div><strong>{{ chapter?.name || '章节制作流程' }}</strong><small>CHAPTER WORKSPACE</small></div></div><nav aria-label="章节制作进度"><AppButton v-for="item in steps" :key="item.id" variant="soft" :active="step === item.id" :class="{ 'is-complete': step > item.id }" @click="go(item.id)"><span><Check v-if="step > item.id" :size="14" /><component :is="item.icon" v-else :size="14" /></span><div><strong>{{ item.label }}</strong><small>{{ item.sub }}</small></div></AppButton></nav></header><section v-if="step === 1" class="workflow-content"><div class="content-hero"><span class="eyebrow">CONTENT UNDERSTANDING</span><h1>从文字建立视觉世界</h1><p>提取本章角色、场景与关键道具，为后续画布提供一致的视觉资产。</p><AppButton variant="primary" :disabled="extracting" :loading="extracting" @click="extract"><Sparkles v-if="!extracting" :size="16" />{{ extracting ? '正在提取…' : assets.length ? '重新提取实体' : '开始内容理解' }}</AppButton></div><article class="chapter-content"><header><strong>第 {{ chapter?.number }} 章 · {{ chapter?.name }}</strong><small>{{ (chapter?.content || '').length }} 字</small></header><p>{{ chapter?.content || '本章暂无正文内容' }}</p></article><div v-if="assets.length" class="entity-strip"><span v-for="asset in assets" :key="asset.id">{{ asset.canonical_name }}</span></div></section><section v-else-if="step === 2" class="workflow-content asset-workspace"><div class="section-title"><div><span class="eyebrow">VISUAL ASSETS</span><h1>视觉资产</h1><p>完善角色、场景和道具的统一参考图。</p></div><div class="header-actions"><AppButton variant="secondary" :loading="batchGenerating" :disabled="batchGenerating" @click="batchGenerate"><Sparkles v-if="!batchGenerating" :size="15" />{{ batchGenerating ? '批量生成中…' : '补齐全部主图' }}</AppButton><AppButton variant="primary" @click="go(3)">进入创作画布<Workflow :size="16" /></AppButton></div></div><section v-for="group in groups" :key="group.type" class="asset-group"><header><component :is="group.icon" :size="17" /><strong>{{ group.label }}</strong><small>{{ group.items.length }}</small></header><div class="asset-grid"><article v-for="asset in group.items" :key="asset.id" class="asset-card"><div class="asset-media"><img v-if="asset.main_image" :src="asset.main_image" :alt="asset.canonical_name"><Image v-else :size="28" /><div class="asset-actions"><AppButton type="button" variant="secondary" size="sm" :loading="processing.includes(asset.id)" :disabled="processing.includes(asset.id)" @click="generate(asset)"><RefreshCw v-if="!processing.includes(asset.id)" :size="15" />{{ asset.main_image ? '重新生成' : '生成主图' }}</AppButton><label><Upload :size="15" />上传<input type="file" accept="image/*" @change="upload(asset, $event)"></label></div></div><div class="asset-angles"><label v-for="field in (['angle_image_1', 'angle_image_2'] as const)" :key="field"><img v-if="asset[field]" :src="asset[field]" alt="侧面参考图"><Upload v-else :size="14" /><input type="file" accept="image/*" @change="uploadAngle(asset, field, $event)"></label></div><div class="asset-copy"><header><strong>{{ asset.canonical_name }}</strong><span><AppButton type="button" variant="ghost" size="xs" icon-only aria-label="编辑资产" @click="openEdit(asset)"><Pencil :size="14" /></AppButton><AppButton type="button" variant="danger" size="xs" icon-only aria-label="删除资产" @click="removeAsset(asset)"><Trash2 :size="14" /></AppButton></span></header><p>{{ asset.description || '暂无描述' }}</p><small>{{ asset.aliases?.join(' · ') }}</small></div></article></div></section></section><CreativeCanvas v-else :key="chapterId" :novel-id="novelId" :chapter-id="chapterId" /><div v-if="editing" class="modal-backdrop" @click.self="editing = null"><form class="modal" @submit.prevent="saveAsset"><header><h2>编辑视觉资产</h2><AppButton type="button" variant="ghost" size="sm" icon-only aria-label="关闭" @click="editing = null"><X :size="18" /></AppButton></header><label>名称<input v-model="editForm.canonical_name" required></label><label>别名<input v-model="editForm.aliases"></label><label>描述<textarea v-model="editForm.description" rows="4" /></label><label>固有特征<textarea v-model="editForm.base_traits" rows="3" /></label><footer><AppButton type="button" variant="secondary" @click="editing = null">取消</AppButton><AppButton type="submit" variant="primary">保存资产</AppButton></footer></form></div></div></template>
